import onnx, numpy as np
from onnx import numpy_helper
def load(p):
    m=onnx.load(p); I={i.name:numpy_helper.to_array(i) for i in m.graph.initializer}
    Ws=[];bs=[]
    for n in m.graph.node:
        if n.op_type=='MatMul': Ws.append(I[n.input[1]])
        if n.op_type=='Add': bs.append(I[n.input[1]])
        if n.op_type=='Gemm': Ws.append(I[n.input[1]].T); bs.append(I[n.input[2]])
    return Ws,bs
W1,b1=load('/nets/net1.onnx'); W2,b2=load('/nets/net2.onnx')
print([w.shape for w in W1])
for k,(a,b,c,d) in enumerate(zip(W1,W2,b1,b2)):
    z1=np.where(np.all(a==0,axis=0))[0]; z2=np.where(np.all(b==0,axis=0))[0]
    print(k,'zero out-units net1',len(z1),'net2',len(z2), (z2+1).tolist())
    D=a-b; print('  |dW|max',abs(D).max(),'|W1|max',abs(a).max(),'db max',abs(c-d).max())
    # relation: is W2 = W1 with zeroed entries?
    mask=(b==0)&(a!=0); other=(b!=0)
    print('  zeroed entries',mask.sum(),'max diff on others',abs(D[other]).max() if other.any() else 0)
import re
print(open('/nets/spec.vnnlib').read()[:800])

